#!/usr/bin/env bash
# Build .deb, .rpm, Arch (.pkg.tar.zst) and Alpine (.apk) packages from a static
# Linux binary with nfpm (packaging/nfpm.yaml).
#
# Usage: scripts/package.sh BINARY ASSETS ARCH OUTDIR [VERSION]
#   ASSETS holds pdeck.1 and completions/{pdeck.bash,_pdeck,pdeck.fish}
#   (generated by the binary itself: `pdeck --man`, `pdeck --completions SHELL`).
#   ARCH is amd64 or arm64; VERSION defaults to the one in Cargo.toml.
#   scripts/package.sh target/x86_64-unknown-linux-musl/static/pdeck target/assets amd64 dist
set -euo pipefail
if [[ $# -lt 4 ]]; then
  echo "usage: scripts/package.sh BINARY ASSETS ARCH OUTDIR [VERSION]" >&2
  exit 2
fi
[[ -f "$1" ]] || { echo "package: no binary at $1" >&2; exit 1; }
[[ -f "$2/pdeck.1" ]] || { echo "package: no $2/pdeck.1" >&2; exit 1; }
bin=$(cd "$(dirname "$1")" && pwd)/$(basename "$1")
assets=$(cd "$2" && pwd)
arch=$3
mkdir -p "$4"
out=$(cd "$4" && pwd)
cd "$(dirname "$0")/.."
version=${5:-$(sed -n 's/^version = "\(.*\)"$/\1/p' Cargo.toml | head -1)}
case "$arch" in
  amd64 | arm64) ;;
  *) echo "package: ARCH must be amd64 or arm64, not $arch" >&2; exit 2 ;;
esac
command -v nfpm >/dev/null || { echo "package: nfpm not found (https://nfpm.goreleaser.com/install/)" >&2; exit 1; }

rm -rf target/package
mkdir -p target/package/completions
cp "$bin" target/package/pdeck
gzip -9n < "$assets/pdeck.1" > target/package/pdeck.1.gz
cp "$assets/completions/pdeck.bash" "$assets/completions/_pdeck" "$assets/completions/pdeck.fish" \
  target/package/completions/
for format in deb rpm archlinux apk; do
  VERSION=$version ARCH=$arch \
    nfpm package --config packaging/nfpm.yaml --packager "$format" --target "$out/"
done
ls -l "$out"
